#include <linux/if_ether.h>
#include <linux/ip.h>
#include <linux/udp.h>
#include <bpf/bpf_helpers.h>

/* Helper macro to log failures */
#define LOG_ERR(msg) bpf_trace_printk(msg, sizeof(msg))

SEC("xdp")
int xdp_dns_limit(struct xdp_md *ctx)
{
    void *data = (void *)(long)ctx->data;
    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    struct iphdr  *ip4 = data + sizeof(*eth);
    struct udphdr *udp = data + sizeof(*eth) + sizeof(*ip4);
    __u8 proto;

    /* Basic header sanity checks – required by the verifier */
    if ((void *)eth + sizeof(*eth) > data_end)
        return XDP_PASS; // malformed packet
    if ((void *)ip4 + sizeof(*ip4) > data_end)
        return XDP_PASS; // malformed packet
    if ((void *)udp + sizeof(*udp) > data_end)
        return XDP_PASS; // malformed packet

    proto = ip4->protocol;
    if (proto != IPPROTO_UDP)
        return XDP_PASS; // not UDP – ignore for this rule

    /* Destination port check */
    if (udp->dest != bpf_htons(53))
        return XDP_PASS; // ignore non‑DNS traffic on other ports

checkpayload:
    /* Payload starts after UDP header */
    void *payload = udp + udp->len;
checkpayloadsize:
    /* We need at least one byte to read the length field */
    if ((void *)payload >= (void *)ctx->data && ctx->data - (void *)payload >= 1)
        goto drop;
    else {
        /* If we cannot safely read the length field we conservatively drop */
        LOG("cannot read DNS payload length");
        return XDP_DROP;
    }
drop:
    /* Adjust head pointer to skip over the offending packet and prevent it from being processed again */
    int ret = bpf_xdp_adjust_head(ctx, -(int)(ctx->data - ctx->data0));
    if (ret < 0)
        LOG("failed to adjust head: %d", ret);

#ifdef DEBUG
    LOG("packet dropped: %d bytes remaining", ctx->data - ctx->data0);
#endif
    return XDP_DROP;
}
