    __uint(max_entries, 1);
    __type(key, __u32);
    __type(value, __u64);
} tcp_seg_cnt SEC(".maps");

/* Helper macro for readability */
#define PERCPU(idx) (*(__u64 *)((char *)tcp_seg_cnt.values + (idx) * sizeof(__u64)))

/* kprobe handler attached to tcp_v4_rcv */
SEC("kprobe/tcp_v4_rcv")
int handle_tcp(struct pt_regs *ctx)
{
    /* The kernel passes a pointer to the skb in ctx->di on x86 */
    struct sk_buff *skb = (struct sk_buff *)ctx->di;

    /* Defensive checks – ensure we are dealing with IPv4/TCP packets */
    if (skb->protocol != htons(ETH_P_IP) ||
        !(skb->protocol == htons(ETH_P_IP) && skb->ip_summed == CHECKSUM_UNNECESSARY))
        return 0; // not our target packet

    /* Increment the per‑CPU counter for this CPU */
    __u32 key = 0;
    __u64 *val = bpf_map_lookup(&tcp_seg_cnt, &key);
    if (!val)
        return 0; // should never happen because map was created with max=1
    PERCPU(key)++;

    /* Optional: record timestamp for latency analysis – omitted here */
    return 0;
}

char _license[] SEC("license") = "GPL";
