    void *data_end = (void *)(long)ctx->data_end;
    struct ethhdr *eth = data;
    struct iphdr *iph = data + sizeof(*eth);
    struct ipv6hdr *ip6h = data + sizeof(*eth);
    struct iphdr *frag;
    __u8 frag_hdr[sizeof(struct iphdr)];
    __u16 off;

