/*
 * Minimal character device driver demonstrating .read/.write with copy_to_user()
 * and copy_from_user().  The driver allocates a static buffer of 256 bytes,
 * exposes it via /dev/mydev (major 200, minor 0), and performs strict
 * bounds checking on all user‑supplied lengths.
 */
#include <linux/module.h>
#include <linux/fs.h>
#include <linux/uaccess.h>
#include <linux/miscdevice.h>
#include <linux/kernel.h>

/* Size of the internal buffer – must be <= PAGE_SIZE */
#define BUF_SIZE 256

static char devbuf[BUF_SIZE];
static size_t devbuf_len = BUF_SIZE;   /* current length of data stored */

/* ------------------------------------------------------------------ */
/* .read implementation – copies data from kernel buffer to user space   */
static ssize_t mydev_read(struct file *filp,
                           char __user *buf,
                           size_t count,
                           loff_t *ppos)
{
    if (count == 0)
        return 0;                     /* nothing to read */

    /* Ensure we never write past the end of devbuf */
    if (*ppos >= BUF_SIZE)
        return -EINVAL;               /* EOF or out‑of‑range request */

    /* Clamp count to remaining bytes in devbuf */
    if (count > BUF_SIZE - *ppos)
        count = BUF_SIZE - *ppos;

    if (copy_to_user(buf, devbuf + *ppos, count))
        return -EFAULT;               /* bad user pointer */

    *ppos += count;
    return count;
}

/* ------------------------------------------------------------------ */
/* .write implementation – copies data from user space into kernel buffer*/
static ssize_t mydev_write(struct file *filp,
                            const char __user *buf,
                            size_t count,
                            loff_t *ppos)
{
    if (count == 0)
        return 0;

    /* Prevent overflow of devbuf */
    if (*ppos >= BUF_SIZE)
        return -EINVAL;

    /* Clamp count to remaining space in devbuf */
    if (count > BUF_SIZE - *ppos)
        count = BUF_SIZE - *ppos;

    if (copy_from_user(devbuf + *ppos, buf, count))
        return -EFAULT;               /* bad user pointer */

    *ppos += count;
    return count;
}

/* ------------------------------------------------------------------ */
/* Device registration – expose major number 200 (arbitrary)          */
static struct miscdevice mydev = {
    .minor = MISCDEV1,
    .name   = "mydev",
};
MODULE_ALIAS("misc:mydev");
MODULE_LICENSE("GPL");
MODULE_AUTHOR("SFT Example Generator");
MODULE_DESCRIPTION("Demo character device using copy_* helpers");
module_init(mydevinit);
module_exit(mydevexit);

static int mydevinit(void)
{
    int ret;
    pr_info("mydev: initializing\n");
    ret = miscdevice(&mydev);
    if (ret) {
        pr_err("mydev: miscdevice registration failed %d\n", ret);
        return ret;
    }
    pr_info("mydev: miscdevice registered\n");
    return 0;
}
static void mydevexit(void)
{
    pr_info("mydev: exiting\n");
}
