/*
 * Example: using spinlocks in an interrupt handler (top half) and mutexes in the
 * bottom‑half workqueue.
 *
 * The top‑half runs with interrupts disabled on the local CPU.  It must be
 * extremely fast and cannot sleep.  A spinlock provides mutual exclusion without
 * sleeping, making it ideal for protecting data structures that are also accessed
 * from other contexts (e.g., process context).
 *
 * The bottom‑half runs in process context (a workqueue) where sleeping is allowed.
 * Here we use a mutex to protect longer‑running operations such as I/O or memory
 * allocation.
 */
#include <linux/spinlock.h>
#include <linux/mutex.h>
#include <linux/interrupt.h>
#include <linux/workqueue.h>

/* Shared data protected by both contexts */
static int shared_counter;
static DEFINE_SPINLOCK(shared_lock);
static DEFINE_MUTEX(shared_mutex);

/* Top‑half (interrupt) – runs with interrupts enabled */
static irqreturn_t my_irq_handler(int irq, void *dev_id)
{
    unsigned long flags;
    /* Protect access to shared_counter */
    spin_lock_irqsave(&shared_lock, flags);
    shared_counter++;
    /* ... other fast work ... */
    spin_unlock_irqrestore(&shared_lock, flags);
    return IRQ_HANDLED;
}

/* Bottom‑half – scheduled via workqueue */
static void my_bottom_half(struct work_struct *work)
{
    /* Use a mutex because we may sleep */
    mutex_lock(&shared_mutex);
    /* Perform potentially blocking I/O or allocate memory */
    if (need_to_sleep()) {
        /* Sleep safely – allowed here */
        msleep(10);
        /* ... more work ... */
        mutex_unlock(&shared_mutex);
    } else {
        /* Fast path without sleeping */
        do_fast();
        mutex_unlock(&shared_mutex);
    }
}
```
**Explanation of correctness**
- **Top half**: `spinlock` + `spin_*` helpers disable local interrupts while holding the lock, guaranteeing that no other interrupt on the same CPU can pre‑empt this critical section. This satisfies the requirement that spinlocks cannot be held across schedule points.
- **Bottom half**: `mutex` can block; therefore it is placed only in process context where sleeping is permitted.
- **Pitfalls to avoid**:
  1. **Using a mutex in the top half** would cause a BUG if the lock were taken while interrupts were disabled because the scheduler might need to run another task that also needs the same lock.
  2. **Holding a spinlock across a call that may sleep** (e.g., `schedule()`, `wait()`) leads to deadlock because interrupts remain disabled.
  3. **Mixing both primitives on the same data without proper ordering** can cause race conditions; always protect shared state with either a spinlock or a mutex consistently.
- **Best practice**: Keep interrupt handlers minimal; defer any heavy processing to bottom halves using appropriate synchronization primitives.

