/*
 * Example: Correct use of spinlock (top‑half) and mutex (bottom‑half)
 * -----------------------------------------------------------
 * The kernel documentation states:
 *   - Spinlocks cannot be held across schedule points.
 *   - Mutexes may sleep; they must not be used in interrupt context.
 *
 * We therefore split protection into two contexts:
 *   1. Top‑half (interrupt context): fast, cannot sleep → spinlock.
 *   2. Bottom‑half (process context): can sleep → mutex.
 */

#include <linux/spinlock.h>
#include <linux/mutex.h>
#include <linux/interrupt.h>

/* Shared data protected by both contexts */
static int shared_counter;
static DEFINE_SPINLOCK(shared_counter_lock);
static DEFINE_MUTEX(shared_counter_mutex);

/* ---------- Top‑half (interrupt) ---------- */
static irqreturn_t my_irq_handler(int irq, void *dev_id)
{
    unsigned long flags;
    /* Fast path – must not sleep */
    if (need_to_handle(irq)) {
        /* Protect shared counter without any possibility of sleeping */
        spin_lock(&shared_counter_lock);
        shared_counter++;
        /* ... other minimal work ... */
        spin_unlock(&shared_counter_lock);
    }
    return IRQ_HANDLED;
}

/* ---------- Bottom‑half (process context) ---------- */
static void my_bottom_half(struct workqueue_struct *wq)
{
    /* Process context – we may sleep */
    if (!need_to_sleep()) {
        /* Fast path without any locking – still safe because we are not in IRQ */
        do_fast();
        return;
    }

    /* Slow path – acquire a mutex because we might block */
    mutex_lock(&shared_counter_mutex);

    if (need_to_sleep()) {
        /* Sleep safely – allowed here */
        msleep(10);
        /* ... more work ... */
        mutex_unlock(&shared_counter_mutex);
    } else {
        /* Fast path without any locking – still safe because we are not in IRQ */
        do_fast();
        mutex_unlock(&shared_counter_mutex);
    }
}
```
**Explanation of correctness**
- **Top‑half**: `spinlock` is used because interrupts are disabled on the local CPU (`spin_*` helpers disable preemption). No sleeping is possible, satisfying the rule that spinlocks cannot be held across schedule points.
- **Bottom‑half**: `mutex` is used because we are now in process context where sleeping is permitted. The lock protects `shared_*` data from concurrent access by other CPUs or by other bottom‑half executions.
- **Why this works**: The two contexts never overlap; the top half finishes before the bottom half runs on another CPU or after the same CPU re‑enables interrupts.
- **Common pitfalls**:
  1. Using `mutex` in the top half would cause a BUG if an interrupt occurs while holding the lock because interrupts remain disabled.
  2. Using `spinlock` in the bottom half would also trigger a BUG for similar reasons.
  3. Forgetting to release either lock leads to deadlocks; always pair `spin_*`/`mutex_*` with matching `*_unlock`.

