{
    /* Retrieve the filename from the pt_regs structure */
    const char __user *filename = (const char __user *)PT_REGS_PARM1(ctx);
    /* Copy it into our static buffer safely */
    if (copy_from_user(log_buf, filename, PATH_MAX))
        return; /* In case copy fails – nothing to log */
    log_len = strnlen(log_buf, PATH_MAX);
}

