    pr_info("[shadowmon] loading module\n");

    /* Attach pre‑handler to do_sys_openat2 */
    ret = register_kprobe(&kp);
    if (ret) {
        pr_err("[shadowmon] register kprobe failed: %d\n", ret);
        return ret;
    }

