 * @name:   Name of the SLAB cache (must match the one created by
 *          kmem_cache_create())
 * @size:   Size of the object in bytes (multiple of 8)
 *
 * Returns: Pointer to allocated object on success, NULL on failure.
 */
static void *myobj_alloc(const char *name, size_t size)
{
    struct kmem_cache *cache;
    void *obj;

    /* Validate inputs */
    if (!name || !size || size % 8 != 0) {
        pr_err("Invalid arguments to myobj_alloc\n");
        return NULL;
    }

    /* Look up the cache – this mirrors what kmemcg does internally */
    cache = kmem_cache_find(name);
    if (!cache) {
        pr_err("SLAB cache %s not found\n", name);
        return NULL;
    }

    /* Allocate from the cache */
    obj = kmem_cache_alloc(cache, GFP_KERNEL);
    if (!obj) {
        pr_err("Allocation failed for %s\n", name);
        return NULL;
    }

    /* Optional: initialise fields here */
    memset(obj, 0, size);

    return obj;
}

/*
 * myobj_free - Release an object back to its SLAB cache.
 *
 * @ptr:   Pointer returned by myobj_alloc().
 */
static void myobj_free(void *ptr)
{
    if (!ptr)
        return; /* Nothing to free – defensive check */

    /* The pointer must have been allocated from a dedicated SLAB cache.
     * If it was allocated elsewhere (e.g., via kmalloc), this function
     * should not be called. The caller is responsible for ensuring the
     * correct allocation context.
     */
    kmem_cache_free(ptr); /* Returns memory to the original cache */
}
```
