/*
 * Example implementation of the stateful packet‑dropping hook.
 * It follows the description in Documentation/networking/netfilter-hooks.rst:
 *   - Accept packets that are ESTABLISHED or RELATED.
 *   - Drop all other packets (e.g., INVALID, NEW).
 *
 * The function is intended to be used as an NF_INET_FORWARD hook.
 */
#include <linux/module.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>
#include <linux/netfilter_ipv6.h>
#include <linux/netfilter_bridge.h>
#include <linux/skbuff.h>

/* Forward declaration of the hook prototype */
static unsigned int nf_hook(void *priv,
                           struct sk_buff *skb,
                           const struct nf_hook_state *state);

/* Hook implementation */
static unsigned int nf_hook(void *priv,
                           struct sk_buff *skb,
                           const struct nf_hook_state *state)
{
    /* Retrieve the conntrack entry for this packet */
    struct nf_conntrack *ct = nf_ct_get(skb, state->pf);
    if (!ct)
        return NF_ACCEPT;   /* No conntrack info – treat as non‑matching */

    /* Check for ESTABLISHED or RELATED states */
    if (nfct_is_established(ct) || nfct_is_related(ct)) {
        /* Packet belongs to an existing flow – allow it */
        return NF_ACCEPT;
    }

    /* Anything else (NEW, INVALID, etc.) should be dropped */
    return NF_DROP;
}

/* Register the hook with Netfilter (example for IPv4 forward path) */
static int __init myhook_init(void)
{
    int ret = register_netfilter(&myhook);
    if (ret)
        pr_err("Failed to register myhook: %d\n", ret);
    return ret;
}

static void __exit myhook_exit(void)
{
    unregister_netfilter(&myhook);
}

module_init(myhook_init);
module_exit(myhook_exit);
MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("Stateful packet dropper using conntrack");
```
**Explanation of key parts**
