/*
 * Example Netfilter hook implementing stateful packet dropping.
 *
 * It runs in the NF_INET_FORWARD direction and decides whether to
 * accept or drop a packet based on its conntrack state.
 */
#include <linux/module.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>
#include <linux/netfilter/nfnetlink.h>
#include <linux/netfilter/xtables.h>
#include <linux/skbuff.h>
#include <linux/netfilter/nfnetlink.h>

/* Forward declaration of our custom hook */
static unsigned int myhook(void *priv,
                           struct sk_buff *skb,
                           const struct nf_hook_state *state);

/* Register the hook for IPv4 forward path */
static int __init myhook_init(void)
{
    /* Register with Netfilter for IPv4 forward packets */
    return register_netfilter(&myhook);
}

static void __exit myhook_exit(void)
{
    unregister_netfilter(&myhook);
}

module_init(myhook_init);
module_exit(myhook_exit);
MODULE_LICENSE("GPL");
MODULE_AUTHOR("Example Author");
MODULE_DESCRIPTION("Stateful packet dropper using conntrack");

/* Hook implementation */
static unsigned int myhook(void *priv,
                           struct skb *skb,
                           const struct nf_*state)
{
    /* Retrieve conntrack entry; returns NULL if no entry exists */
    struct nfconntrack *ct = nfct;
    if (!ct)
        return NFACCEPT;   /* No conntrack info – treat as non‑matching */

    /* Check for ESTABLISHED or RELATED states */
    if (nfct->status & NFCTSESTABLISHED ||
        ct->status & NFCTSESTABLISHED ||
        ct->status & NFCTSESTABLISHEDRELATED ||
        ct->status & NFCTSESTABLISHEDRELATED)
        return NFACCEPT;   /* Packet belongs to an existing flow – allow */

    /* Anything else (NEW, INVALID, etc.) should be dropped */
    return NFDROP;
}
```
