/*
 * Example: Memory‑mapped I/O driver for a simple GPIO controller.
 * The driver maps the controller’s register block once during probe,
 * performs reads/writes via ioread*/iowrite* helpers, and
 * unmaps it on remove.
 */
#include <linux/module.h>
#include <linux/platform_device.h>
#include <linux/io.h>          /* ioremap / iounmap */
#include <linux/gpio/driver.h> /* optional GPIO core integration */

/* Register offsets – these are defined by the hardware spec */
#define GPIO_CTRL_REG   0x00   /* Control register */
#define GPIO_DATA_REG   0x04   /* Data register (read‑only) */

static void __iomem *gpio_base;
static int gpio_chip;

static int mydev_probe(struct platform_device *pdev)
{
    struct resource *res;
    int ret;

    /* 1️⃣ Obtain the physical address range from platform data */
    res = platform_get_resource(pdev, IORESOURCE_MEM, 0);
    if (!res)
        return -ENODEV;

    /* 2️⃣ Map the physical region into kernel virtual address space */
    gpio_base = ioremap(res->start, resource_size(res));
    if (!gpio_base)
        return -ENOMEM;

    /* 3️⃣ Register a gpio_chip with the generic GPIO core */
    gpio_chip = devm_gpiochip_add(&pdev->dev, &mydev_gpio,
                                 ARRAY_SIZE(mydev_gpios));
    if (IS_ERR(gpio_chip)) {
        iounmap(gpio_base);
        return PTR_ERR(gpio_chip);
    }

    dev_info(&pdev->dev, "GPIO controller probed successfully\n");
    return 0;
}

static int mydev_remove(struct platform_device *pdev)
{
    /* 4️⃣ Unregister the gpio chip – this also releases any resources */
    devm_gpiochip_remove(&pdev->dev);

    /* 5️⃣ Unmap the MMIO region when the device disappears or on error path */
    iounmap(gpio_base);
    gpio_base = NULL;

    dev_info(&pdev->dev, "GPIO controller removed\n");
    return 0;
}

/* Helper to read a single bit from the data register */
static int mydev_getbit(void)
{
    u32 val = ioread32(gpio_base + GPIO_DATA_REG);
    return !!(val & BIT(0));   /* BIT macro expands to (1U << n) */
}

/* Helper to write a single bit to the control register */
static void mydev_setbit(bool enable)
{
    u32 val = ioread32(gpio_base + GPIO_CTRL_REG);
    if (enable)
        val |= BIT(1);          /* Set bit 1 to enable output mode */
    else
        val &= ~BIT(1);         /* Clear bit 1 to disable output mode */
    iowrite32(val, gpio_base + GPIO_CTRL_REG);
}

MODULE_LICENSE("GPL");
MODULE_{AUTHOR("Example Author"), DESCRIPTION("Memory‑mapped I/O driver example");}
```
### Explanation of key steps
1. **Resource acquisition** – `platform_*` helpers retrieve the physical address range from board description (`IORESOURCE_*`). This abstracts away board‑specific details.
2. **Mapping** – `ioremap()` creates a non‑cached virtual mapping for the whole register block (`resource size`). The returned pointer is marked `__iomem` to remind developers that normal dereferencing is illegal; all accesses must go through accessor helpers (`ioread*`, `iowrite*`).
3. **Error handling** – If `ioremap()` fails we abort probing; if `devm_*` registration fails we clean up with `iounmap()`.
4. **Concurrency considerations** – While holding an MMIO mapping you should avoid sleeping or taking locks that may block for long periods; otherwise you risk deadlocks with other drivers that also need exclusive access to the same bus.
5. **Unmapping** – `iounmap()` releases the virtual mapping and invalidates any cached accesses. It must be called exactly once for each successful `ioremap()`.
6. **Accessors** – Use `ioread32()` / `iowrite32()` which include appropriate memory barriers on architectures where needed.
7. **GPIO integration** – The example registers a generic GPIO chip so that userspace can interact via `/sys/class/gpio`. This demonstrates how MMIO drivers fit into larger subsystems.
8. **Cleanup** – In `remove()` we first unregister the GPIO chip (which also frees any allocated resources) and then call `iounmap()`.
9. **Safety notes**:
   - Never cast `void __iomem *` to a regular pointer and dereference it directly.
   - Always pair every successful `ioremap()` with a matching `iounmap()`.
   - Use proper locking (e.g., spinlocks) around concurrent MMIO accesses if multiple contexts may touch the same registers.
   - Validate all offsets against known hardware limits before reading/writing.
