#include <linux/module.h>
#include <linux/kernel.h>
#include <linux/init.h>
#include <linux/sched.h>          // for struct task_struct
#include <linux/rcupdate.h>        // for rcu_read_lock() / rcu_read_unlock()

/* Helper macro to print a process entry */
#define PRINT_PROCESS(p)                     \
    pr_info("PID %d (%s):\n", (p)->pid, (p)->comm)

static int __init tasklist_demo_init(void)
{
    unsigned long flags;
    struct task_struct *task;
    int count = 0;

    pr_info("tasklist demo module loaded\n");

    /* Acquire the global tasklist spinlock */
    spin_lock(&tasklist_lock);

    /* Iterate over every active task using RCU */
    rcu_read_lock();
    for_each_process(task) {
        if (!task)
            continue;               // safety guard – should never happen
        count++;
        PRINT_PROCESS(task);
    }
    rcu_read_unlock();

    pr_info("Total processes: %d\n", count);

    /* Release the spinlock before exiting */
    spin_unlock(&tasklist_lock);
    return 0;
}

static void __exit tasklist_demo_exit(void)
{
    pr_info("tasklist demo module unloaded\n");
}

module_init(tasklist_demo_init);
module_exit(tasklist_demo_exit);
