/* Forward declaration of the global tasklist structure – in real code this
 * would be provided by the kernel core or a test harness.
 */
extern struct {
    struct tasklist {
        struct tasklist **tasks;   /* array of pointers */
        unsigned int nr;
    } *tasklist;
} global;

/* ------------------------------------------------------------------- */
/* Helper to safely read a pointer from the tasks array under a spinlock */
static inline struct tasklist **get_taskptr(unsigned int idx)
{
    unsigned long flags;
    struct tasklist **p;

    spin_lock(&global.tasklist->lock);
    p = &global.tasklist->tasks[idx];
    if (!*p) {
        /* Empty slot – keep it NULL to avoid dereferencing garbage */
        p = NULL;
    }
    spin_unlock(&global.tasklist->lock);
    return p;
}

/* ------------------------------------------------------------------- */
/* Spinlock version – safe because we hold the lock while accessing the array */
static int __init spinlock_demo(void)
{
    unsigned int i, nr = global.tasklist->nr;
    struct tasklist **ptrs = get_taskptr(0);

    pr_info("[spinlock] Iterating over %u tasks\n", nr);
    for (i = 0; i < nr; ++i) {
        if (!ptrs[i])
            continue;               /* skip empty slots */
        pr_info("PID %d (%s):\n", ptrs[i]->pid,
                ptrs[i]->comm ? ptrs[i]->comm : "unknown");
    }
    pr_info("[spinlock] Done\n");
    return 0;
}

/* ------------------------------------------------------------------- */
/* RCU version – uses rcu_* helpers which are safe without holding a lock */
static int __init rcu_demo(void)
{
    unsigned int i, nr = global.tasklist->nr;
    struct tasklist **ptrs = get_taskptr(0);

    pr_info("[rcu] Iterating over %u tasks using RCU\n", nr);
    rcu_read_lock();
    for (i = 0; i < nr; ++i) {
        if (!ptrs[i])
            continue;
        pr_info("PID %d (%s):\n", ptrs[i]->pid,
                ptrs[i]->comm ? ptrs[i]->comm : "unknown");
    }
    rcu_read_unlock();
    pr_info("[rcu] Done\n");
    return 0;
}

/* ------------------------------------------------------------------- */
static void __exit demo(void)
{
    pr_info("demo module unloaded\n");
}

module_init(spinlock_demo);
module_exit(demo);
