/*
 * netfilter_ipv4_check_fragment.c – Drop fragmented IPv4 packets
 *
 * This helper is intended to be used as a Netfilter hook (e.g., `NF_INET_PRE_ROUTING`
 * or `NF_INET_LOCAL_IN`). It verifies that the packet is IPv4 and that the
 * fragment offset field is zero before allowing it through.
 */
#include <linux/skbuff.h>   /* for struct sk_buff */
#include <linux/ip.h>       /* for IPPROTO_IP */

/* Return 0  – packet accepted (or not relevant for this hook)
 * Return -1 – drop the packet (Netfilter action)
 */
int netfilter_ipv4_check_fragment(struct sk_buff *skb)
{
    u8 proto;
    u16 frag;

    /* 1️⃣ Verify that the protocol field is set to IPv4 (0x0800) */
    if (skb->protocol != htons(ETH_P_IP)) {
        /* Non‑IPv4 traffic – let it continue */
        return 0;
    }

    /* 2️⃣ Extract the fragment offset from the IP header.
     * The IPv4 header starts at skb->data + sizeof(struct iphdr).
     */
    const struct iphdr *iph = ip_hdr(skb);
    if (!iph) {
        /* Malformed packet – cannot safely read fields */
        return -1;
    }

    frag = ntohs(iph->frag_off);

    /* 3️⃣ Fragmentation rules (RFC 791):
     *   - If fragments are present, they must have offset == 0.
     *   - Offset == 0 means this is the first fragment of a reassembled packet.
     */
    if (frag != 0) {
        /* Non‑zero offset → this fragment belongs to a reassembled packet.
         * Reject it to avoid out‑of‑order delivery or potential DoS.
         */
        pr_debug("netfilter: dropping non‑zero fragment offset %u\n", frag);
        return -1;   /* Netfilter will drop the packet */
    }

    /* All checks passed – safe to continue processing */
    return 0;
}
```
### Explanation of key steps
1. **Protocol check** – `skb->protocol` holds the Ethernet type in network byte order. We compare it against `htons(ETH_P_IP)` (`ETH_P_IP` = 0x0800). If it differs, we assume an unsupported protocol and let the packet pass.
2. **Header extraction** – `ip_hdr(skb)` returns a pointer to the IPv4 header located at `skb->data + sizeof(struct iphdr)`. The helper macro `iphdr()` performs this conversion safely under normal circumstances.
3. **Fragment offset validation** – The `frag` field encodes both offset and MF flag in bits 3‑5 of the first byte of the IP header. We mask with `IPPROTO_*` helpers (`ntohs`) and compare against zero.
4. **Return semantics** – Netfilter expects an integer action: `NFPROTO_*` constants map to `-1` for drop and other values for accept/continue. Returning `-1` signals a drop; returning `0` means “no action”.
5. **Safety notes** – The function never dereferences beyond what is guaranteed by Netfilter’s hook contract; all pointer checks are performed before any access.

This code can be compiled into a kernel module or linked into an existing Netfilter module that registers it as a pre‑routing hook.

