/*
 * netfilter_ipv4_check_fragment.c – Drop fragmented IPv4 packets
 *
 * This module registers a simple Netfilter hook that inspects the
 * skb->protocol field and the first byte of the IP header to ensure that
 * only non‑fragmented IPv4 packets are allowed through.
 */
#include <linux/module.h>
#include <linux/skbuff.h>
#include <linux/ip.h>
#include <linux/netfilter.h>
#include <linux/netfilter_ipv4.h>

/* Hook prototype expected by nf_register_net_hook() */
static unsigned int my_hook(void *priv,
                             struct sk_buff *skb,
                             const struct nf_hook_state *state)
{
    /* The hook receives a pointer to the skb; we can safely read fields */
    u8 proto = skb->protocol;
    const struct iphdr *iph = ip_hdr(skb);

    if (!iph)
        return NF_ACCEPT;   /* malformed packet – let it continue */

    /* Verify that the protocol field is set to IPv4 (0x0800) */
    if (proto != htons(ETH_P_IP))
        return NF_ACCEPT;   /* not an IPv4 packet – allow */

    /* Extract the fragment offset from the IP header */
    u16 frag = ntohs(iph->frag_off);

    /* RFC 791 rule: offset == 0 means this is the first fragment of a reassembled packet.
     * Any non‑zero offset indicates a fragmented packet that should be dropped.
     */
    if (frag != 0)
        return NF_DROP;      /* drop non‑zero offset fragments */

    return NF_ACCEPT;       /* safe to continue processing */
}

static struct nf_hook_ops my_ops = {
    .hook     = my_hook,
    .pf       = NFPROTO_IPV4,
    .hooknum  = NF_INET_PREROUTING,
    .priority = NF_IP6HOOK,
};

static int __init ipv4checkinit(void)
{
    int ret;

    ret = nf_register(&my_ops);
    if (ret)
        pr_err("Failed to register netfilter hook: %d\n", ret);
    else
        pr_info("Netfilter IPv4 check hook registered successfully\n");
    return ret;
}

static void __exit ipv4checkexit(void)
{
    nf_unregister(&my_ops);
}

module_init(ipv4checkinit);
module_exit(ipv4checkexit);
MODULE_LICENSE("GPL");
MODULE_AUTHOR("SFT Example Generator");
MODULE_DESCRIPTION("Netfilter hook that drops fragmented IPv4 packets");
```
