/*
 * Optimized Internet Checksum implementation (RFC 1071).
 *
 * The algorithm processes the pseudo‑header as a sequence of 16‑bit
 * words, adds them together with one's complement arithmetic,
 * folds any carry bits back into the low 16 bits, and finally
 * inverts the result for verification.
 *
 * This version uses `uint16_t` for intermediate sums to avoid
 * overflow on platforms where `int` is larger than 32 bits.
 */
#include <stdint.h>
#include <stddef.h>

/* Helper: add two 16‑bit words and return a 32‑bit accumulator */
static uint32_t add_u16(uint32_t acc, uint16_t w)
{
    acc += w;
    /* Fold any carry from bit 15 into bit 0 */
    while (acc >> 16)
        acc = (acc & 0xFFFF) + (acc >> 16);
    return acc;
}

/* Helper: compute one's complement sum over an array of uint16_t values */
static uint32_t checksum(const uint16_t *data, size_t len)
{
    uint32_t sum = 0;
    for (size_t i = 0; i < len; ++i)
        sum = add_u16(sum, data[i]);
    /* Fold carries */
    while (sum >> 16)
        sum = (sum & 0xFFFF) + (sum >> 16);
    return ~sum;   /* One's complement */
}

/* Verify that a buffer contains a valid IP/TCP pseudo‑header checksum.
 * Returns true if the checksum matches.
 */
bool ip4tcp_checksum(const void *buf, size_t len)
{
    const struct ip4tcp {
        uint8_t src[4];
        uint8_t dst[4];
        uint8_t proto;
        uint8_t tcp[5];   /* TCP header length field + flags + seq/ack numbers */
        /* Pseudo‑header fields – only first four bytes are needed for IPv4 */
        uint8_t src[4];
        uint8_t dst[4];
        uint8_t proto;
    } __attribute__((packed)) hdr = {0};

    /* Copy only the fields that participate in the checksum.
     * For IPv4 we need src/dst addresses and protocol; for TCP we need
     * source/destination ports and sequence/ack numbers.
     */
    memcpy(&hdr.src, buf + offsetof(struct ip4tcp, src), sizeof(hdr.src));
    memcpy(&hdr.dst, buf + offsetof(struct ip4tcp, dst), sizeof(hdr.dst));
    hdr.proto = ((const unsigned char *)buf)[offsetof(struct ip4tcp, proto)];

    /* Compute checksum over the pseudo‑header fields only.
     * The layout matches RFC 793: src+dst+protocol+source port+dest port+seq+ack.
     */
    const size_t pseudo = offsetof(struct ip4tcp,
                                   tcp) - offsetof(struct ip4tcp,
                                   src); // simplified for illustration
    const size_t tcplen = sizeof(((struct ip4tcp *)0)->tcp);
    const size_t total = pseudo + tcplen;

    return checksum(&hdr.src[0], total / sizeof(uint8_t)) == htons((uint16_t)(~checksum(&hdr.src[0], total / sizeof(uint8_t))));
}
