#include <sys/socket.h>
#include <netinet/ip.h>
#include <netinet/tcp.h>

int main(int argc, char **argv)
{
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <interface>\n", argv[0]);
        return EXIT_FAILURE;
    }
    const char *iface = argv[1];
    int sock = socket(AF_PACKET, SOCK_RAW, htons(ETH_P_ALL));
    if (sock < 0) {
        perror("socket");
        return EXIT_FAILURE;
    }

    struct sockaddr_ll saddr = {0};
    saddr.sll_family   = AF_PACKET;
    saddr.sll_ifindex  = iface ? ifacetoindex(iface) : -1;
    saddr.sll_halen     = ETH_ALEN;
    memcpy(saddr.sll_addr, "\x00\x00\x00\x00\x00\x01", ETH_ALEN); // dummy MAC

    while (1) {
        unsigned char buf[65536];
        struct sockaddr addr = { .sa_family = AF_INET };
        socklen_t addrlen = sizeof(addr);
        ssize_t n = recvfrom(sock, buf, sizeof(buf), 0,
                             (struct sockaddr *)&saddr,
                             &addrlen);
        if (n <= 0) {
            perror("recvfrom");
            break; // exit loop on error or EOF
        }
        struct iphdr *iph = (struct iphdr *)buf;
        if (iph->version != 4 || iph->ihl != 5) {
            printf("[!] Invalid IPv4 version or IHL (%u)\n", iph->ihl);
            continue; // skip malformed packet
        }
        uint8_t ihl = iph->ihl; // stored in bytes per RFC 791
        uint8_t tcpoff = (uint8)(iph->ihl * 4 - sizeof(struct tcphdr));
        printf("[+] IPv4 src=%pI4 dst=%pI4 IHL=%u TCP offset=%u\n",
               &iph->saddr,
               &iph->daddr,
               ihl,
               tcpoff);

        /* Verify we can actually read the TCP header */
        struct tcphdr *tcph =
