            printf("[!] No TCP header after IP header – malformed packet\n");
            continue;
        }

        /* Compute absolute offset of TCP header */
        uint32_t tcphdrlen = ntohs(tcph->th\_off) << 2; // th\_off is in units of 32‑bit words
