/*
 * validate_ip_header_checksum - Verify the IP header checksum of an incoming
 * packet and drop it if the checksum is incorrect.
 *
 * Parameters:
 *   pkt   : pointer to the start of the IP header (network byte order).
 *   len   : length of the IP header in bytes (must be >= sizeof(struct iphdr)).
 *
 * Returns:
 *   true  – packet is valid and should be processed further.
 *   false – packet is corrupted; caller should discard it.
 */
bool validate_ip_header_checksum(const uint8_t *pkt, size_t len)
{
    /* Basic sanity checks */
    if (len < sizeof(struct iphdr)) {
        return false; // too short to contain a full header
    }

    /* Compute one's complement sum of all 16‑bit words */
    uint32_t sum = 0;
    const uint16_t *word = (const uint16_t *)pkt;
    for (size_t i = 0; i + 1 < len; i += 2) {
        /* Convert from network to host order for addition */
        uint32_t w = ntohs(word[i]) + ntohs(word[i + 1]);
        sum += w;
    }

    /* Add any remaining byte (if odd length) */
    if (len & 1) {
        sum += pkt[len - 1];
    }

    /* One's complement: invert all bits and add 1 */
    uint32_t cksum = ~sum + 1U;

    /* The checksum field occupies bytes [4]..[5] in network order */
    const uint8_t cksum_bytes[2] = { pkt[4], pkt[5] };
    uint32_t cksum32 = ((uint32_t)cksum << 8) | cksum;

    return cksum32 == htons((uint16_t)cksum);
}
```
