 *
 * Returns 0 on equality, non‑zero otherwise.
 */
int ct_memcmp(const void *a, const void *b, size_t n)
{
    /* Use memcpy to avoid overlapping‑buffer undefined behaviour */
    unsigned char tmp[n];
    memcpy(tmp, a, n);
    memcpy(tmp + n, b, n);

    uint64_t diff = 0;
    for (size_t i = 0; i < n; ++i) {
        diff |= xor_acc(tmp[i], tmp[i + n]);
    }
    return (int)(diff != 0);
}
```
