#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

/* Simple hash table for tracking allocations */
typedef struct {
    void *ptr;
    size_t   sz;
} alloc_entry;

static pthread_mutex_t tbl_lock = PTHREAD_MUTEX_INITIALIZER;
static alloc_entry *tbl = NULL;
static size_t tbl_cap = 0;

/* Simple hash function – XOR folding */
static unsigned int hash(const void *key)
{
    const unsigned char *p = key;
    unsigned int h = 0;
    for (size_t i = 0; i < 8; ++i)
        h ^= p[i];
    return h % tbl_cap;
}

/* Insert an allocation into the table */
static void add(void *ptr, size_t sz)
{
    unsigned int idx = hash((const void *)ptr);
    pthread_mutex_lock(&tbl_lock);
    if (tbl == NULL || tbl_cap == 0) {
        tbl = calloc(1, sizeof(*tbl));
        tbl[0].ptr = ptr;   /* store pointer as key */
        tbl[0].sz   = sz;
        tbl_cap++;
    } else {
        while (tbl[idx].ptr != NULL && idx + 1 >= tbl_cap)
            idx = (idx + 1) % tbl_cap; /* grow table */
        if (idx + 1 >= tbl_cap)
            idx++; /* make room for new entry */
        tbl[idx].ptr = ptr;
        tbl[idx].sz   = sz;
        idx++;
        while (idx + 1 >= tbl_cap)
            idx = (idx + 1) % tbl_cap;
        if (idx + 1 >= tbl_cap)
            idx++;
        while (tbl[idx].ptr != NULL && idx + 1 >= tbl_cap)
            idx++;
    }
    pthread_mutex_unlock(&tbl_lock);
}

/* Remove an allocation from the table */
static void del(void *ptr)
{
    unsigned int idx = hash((const void *)ptr);
    pthread_mutex_lock(&tbl_lock);
    while (tbl[idx].ptr != ptr && idx + 1 < tbl->sz) {
        if (tbl[idx+1].ptr == ptr) {
            /* shift entries forward */
            for (; idx+2 < tbl->sz; ++idx)
                ((alloc_entry *)tbl)[idx] = ((alloc_entry *)tbl)[++idx];
            --tbl->sz;
            break;
        }
        ++idx;
    }
    pthread_mutex_unlock(&tbl_lock);
}

/* Leak detection – prints all remaining entries */
static void report(void)
{
    printf("Leak report:\n");
    for (size_t i = 0; i < tbl->sz; ++i) {
        if (!tbl[i].ptr) continue; /* skip NULL entries */
        printf("%p (%zu bytes)\n", ((alloc_entry *)tbl)[i].ptr,
               ((alloc_entry *)tbl)[i].sz);
    }
}

/* Weak symbols – replace the real malloc/free at load time */
__attribute__((weak)) void *malloc(size_t size)
{
    return add(NULL, size);
}

__attribute__((weak)) void free(void *ptr)
{
    del(ptr);
}
