    if (!heap) {
        fprintf(stderr, "realloc failed\n");
        exit(EXIT_FAILURE);
    }
    memcpy(&((char *)heap)[heap_size], ptr, size);
    heap[heap_size + size] = '\0';
    heap_size += size;
    return ptr;
}

void my_free(void *ptr)
{
    if (!ptr) return; /* ignore NULL */
    total_freed++;
    free(ptr);
}

/* Helper for test harness */
void reset()
{
    free(heap);
    heap = NULL;
    heap_size = 0;
    total_allocated = 0;
    total_freed = 0;
