static void buildSimpleSecCompFilter (__u8 **prog)
{
    struct sock_* filt[] =
      {
       { .code=SECCOMP__LD|SECCOMP__W|SECCOMP__ABS,
         .jt=offsetof(__u8*,nr),          .jf=offsetof(__u8*,nr)+4 },
       { .code=SECCOMP__JEQ|SECCOMP__K,
         .jt=offsetof(__u8*,nr),          .jf=offsetof(__u8*,nr)+4,
         .k=_NR___read },
       { .code=SECCOMP__JEQ|SECCOMP__K,
         .jt=offsetof(__u8*,nr),          .jf=offsetof(__u8*,nr)+4,
         .k=_NR___write },
       { .code=SECCOMP__JEQ|SECCOMP__K,
         .jt=offsetof(__u8*,nr),          .jf=offsetof(__u8*,nr)+4,
         .k=_NR___exit },
       { SECCOMP__RET|SECCOMP__K,.jt=-99,.jf=-99},
       {}
      };
    size tlen;
    tlen=(size)(sizeof(*filt)/sizeof(*filt));
    (*prog)=malloc((tlen+1)*sizeof(**prog));
    memcpy((*prog),(filt),(tlen+1)*sizeof(**prog));
